  "sql": "WITH _base AS (\n  SELECT\n    regions.id AS \"regions.id\",\n    regions.name AS \"regions.name\"\n  FROM regions AS regions\n  WHERE\n    EXISTS(\n      SELECT\n        1\n      FROM customers AS customers\n      INNER JOIN orders AS customers__orders\n        ON customers.id = customers__orders.customer_id\n      WHERE\n        (\n          regions.id = customers.region_id\n          AND customers__orders.order_date >= CAST('2025-01-01' AS DATE)\n        )\n        AND customers__orders.order_date < CAST('2026-01-01' AS DATE)\n    )\n  GROUP BY\n    regions.id,\n    regions.name\n), _cm_regions__customers__orders__id_count AS (\n  SELECT\n    customers__regions.id AS \"orders.customers.regions.id\",\n    customers__regions.name AS \"orders.customers.regions.name\",\n    COUNT(orders.id) AS \"orders.id_count\"\n  FROM orders AS orders\n  LEFT JOIN customers AS customers\n    ON orders.customer_id = customers.id\n  LEFT JOIN regions AS customers__regions\n    ON customers.region_id = customers__regions.id\n  WHERE\n    orders.order_date >= CAST('2025-01-01' AS DATE)\n    AND orders.order_date < CAST('2026-01-01' AS DATE)\n  GROUP BY\n    customers__regions.id,\n    customers__regions.name\n)\nSELECT\n  _base.\"regions.id\",\n  _base.\"regions.name\",\n  COALESCE(_cm_regions__customers__orders__id_count.\"orders.id_count\", 0) AS \"regions.orders_2025\"\nFROM _base\nLEFT JOIN _cm_regions__customers__orders__id_count\n  ON _base.\"regions.id\" IS NOT DISTINCT FROM _cm_regions__customers__orders__id_count.\"orders.customers.regions.id\"\n  AND _base.\"regions.name\" IS NOT DISTINCT FROM _cm_regions__customers__orders__id_count.\"orders.customers.regions.name\"\nORDER BY\n  _base.\"regions.id\" ASC,\n  _base.\"regions.name\" ASC\nLIMIT 101"
}

